import DashboardLayout from "@/components/DashboardLayout";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { trpc } from "@/lib/trpc";
import { useAuth } from "@/_core/hooks/useAuth";
import { isProjectActive } from "../../../shared/projectStatus";
import { ArrowLeft, CalendarClock, CheckCircle2, CircleDollarSign, Clock3, FileCheck2, FolderKanban, HandCoins, HardHat, Landmark, MessageSquare, Plus, ReceiptText, ShieldAlert, WalletCards } from "lucide-react";
import { useLocation } from "wouter";
import { useMemo, useState } from "react";

const statusLabels = {
  on_track: { label: "على المسار", className: "bg-emerald-50 text-emerald-700 border-emerald-200" },
  warning: { label: "يحتاج متابعة", className: "bg-amber-50 text-amber-700 border-amber-200" },
  critical: { label: "خطر / متأخر", className: "bg-rose-50 text-rose-700 border-rose-200" },
};

const money = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const classificationLabels: Record<string, string> = { operational: "تشغيلي", administrative: "إداري" };

export default function Home() {
  const [, setLocation] = useLocation();
  const { user } = useAuth();
  const { data: summaries = [], isLoading } = trpc.erp.dashboard.summary.useQuery();
  const { data: companySummary } = trpc.erp.dashboard.companySummary.useQuery();
  const [selectedProjectId, setSelectedProjectId] = useState<number | null>(null);
  const selectedSummary = useMemo(() => summaries.find((item) => item.project.id === selectedProjectId) ?? summaries[0] ?? null, [summaries, selectedProjectId]);
  const { data: selectedDetailReport } = trpc.erp.reports.projectStageDetail.useQuery({ projectId: selectedSummary?.project.id ?? 0 }, { enabled: Boolean(selectedSummary?.project.id) });
  const { data: selectedCashFlow } = trpc.erp.reports.cashFlow.useQuery({ projectId: selectedSummary?.project.id ?? 0 }, { enabled: Boolean(selectedSummary?.project.id) });
  const { data: approvalRows = [] } = trpc.erp.approvals.list.useQuery();
  const sendProjectAlert = trpc.erp.dashboard.sendProjectAlert.useMutation({ onSuccess: (result) => window.alert(`تم إرسال التنبيه إلى ${result.recipientCount} مدير مشروع.`), onError: (error) => window.alert(error.message) });
  const shortcutTotals = summaries.reduce((totals, item) => ({
    plannedBudget: totals.plannedBudget + item.plannedBudget,
    plannedRevenue: totals.plannedRevenue + (item.plannedRevenue ?? 0),
    plannedZakat: totals.plannedZakat + (item.plannedZakat ?? 0),
    plannedProfit: totals.plannedProfit + (item.plannedProfit ?? 0),
    actualCost: totals.actualCost + item.actualCost,
    outstandingCost: totals.outstandingCost + item.outstandingCost,
    recognizedRevenue: totals.recognizedRevenue + item.recognizedRevenue,
    collectionsReceived: totals.collectionsReceived + item.collectionsReceived,
    payrollOutstanding: totals.payrollOutstanding + item.payrollOutstanding,
    materialsExpenses: totals.materialsExpenses + item.materialsExpensesTotal,
    operationalExpenses: totals.operationalExpenses + item.operationalExpensesTotal,
    administrativeExpenses: totals.administrativeExpenses + item.administrativeExpensesTotal,
    payrollTotal: totals.payrollTotal + item.payrollTotal,
    subcontractorCostsTotal: totals.subcontractorCostsTotal + item.subcontractorCostsTotal,
    totalExpenses: totals.totalExpenses + item.totalExpenses,
    cashGap: totals.cashGap + item.cashGap,
    pendingApprovals: totals.pendingApprovals + item.pendingApprovals,
  }), { plannedBudget: 0, plannedRevenue: 0, plannedZakat: 0, plannedProfit: 0, actualCost: 0, outstandingCost: 0, recognizedRevenue: 0, collectionsReceived: 0, payrollOutstanding: 0, materialsExpenses: 0, operationalExpenses: 0, administrativeExpenses: 0, payrollTotal: 0, subcontractorCostsTotal: 0, totalExpenses: 0, cashGap: 0, pendingApprovals: 0 });
  const totalBudget = shortcutTotals.plannedBudget;
  const totalPlannedRevenue = shortcutTotals.plannedRevenue;
  const totalPlannedZakat = shortcutTotals.plannedZakat;
  const totalPlannedProfit = shortcutTotals.plannedProfit;
  const totalActual = shortcutTotals.actualCost;
  const totalOutstanding = shortcutTotals.outstandingCost;
  const criticalCount = summaries.filter((item) => item.status === "critical").length;
  const warningCount = summaries.filter((item) => item.status === "warning").length;
  const totalRevenue = shortcutTotals.recognizedRevenue;
  const totalCollections = shortcutTotals.collectionsReceived;
  const totalPayrollOutstanding = shortcutTotals.payrollOutstanding;
  const totalCashGap = shortcutTotals.cashGap;
  const selectedExpenseTotals = selectedSummary ? { materials: selectedSummary.materialsExpensesTotal, operational: selectedSummary.operationalExpensesTotal, payroll: selectedSummary.payrollTotal, administrative: selectedSummary.administrativeExpensesTotal, total: selectedSummary.totalExpenses } : { materials: shortcutTotals.materialsExpenses, operational: shortcutTotals.operationalExpenses, payroll: shortcutTotals.payrollTotal, administrative: shortcutTotals.administrativeExpenses, total: shortcutTotals.totalExpenses };
  const totalPendingApprovals = shortcutTotals.pendingApprovals;

  return (
    <DashboardLayout>
      <div dir="rtl" className="min-h-screen bg-[#f7f8fa] px-4 py-6 sm:px-8 lg:px-10">
        <div className="mx-auto max-w-7xl space-y-8">
          <header className="flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between">
            <div className="w-full lg:order-2 lg:w-72"><label className="mb-2 block text-xs font-semibold text-slate-500">المشروع المعروض في المؤشرات</label><select value={selectedSummary ? String(selectedSummary.project.id) : ""} onChange={(event) => setSelectedProjectId(Number(event.target.value))} className="h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm text-[#18324b] shadow-sm outline-none focus:border-[#b28a3b]"><option value="" disabled>اختر مشروعًا</option>{summaries.map((item) => <option key={item.project.id} value={item.project.id}>{item.project.name}</option>)}</select></div>
            <div>
              <p className="mb-2 text-sm font-semibold tracking-wide text-[#b28a3b]">{user?.role === "general_manager" ? "واجهة المدير العام التنفيذية" : "مركز القيادة التنفيذية"}</p><div className="mb-2 inline-flex rounded-full border border-[#eadfca] bg-[#fcfaf5] px-3 py-1 text-xs font-semibold text-[#8b6b2f]">{user?.role === "general_manager" ? "عرض تقارير وموافقات فقط · واجهة مختلفة عن المحاسب ومدير المشاريع" : "لوحة متابعة تنفيذية"}</div>
              <h1 className="text-3xl font-bold tracking-tight text-[#18324b] sm:text-4xl">صورة المشروع في لحظة</h1>
              <p className="mt-2 max-w-2xl text-sm leading-7 text-slate-500">اعرف من أول نظرة هل التنفيذ يسير وفق المخطط، وما سبب أي انحراف في الميزانية أو المراحل أو السيولة.</p>
            </div>
            {user?.role !== "general_manager" && <Button onClick={() => setLocation("/projects")} className="gap-2 bg-[#18324b] hover:bg-[#244767]">
              <Plus className="h-4 w-4" />
              إضافة مشروع
            </Button>}
          </header>

          {selectedSummary && <ExecutionBoard summary={selectedSummary} rows={selectedDetailReport?.rows.filter((row) => row.rowType === "stage") ?? []} />}

          {selectedSummary && <BudgetOverview summary={selectedSummary} budgetParents={selectedDetailReport?.budgetParents ?? []} />}

          {selectedSummary && <section className="grid gap-4 rounded-3xl bg-[#18324b] p-5 text-white shadow-sm lg:grid-cols-[1.3fr_1fr_1fr]"><TimeGauge title="عداد المرحلة النشطة" subtitle={selectedSummary.activeStage?.name ?? "لا توجد مرحلة نشطة"} start={selectedSummary.activeStage?.plannedStart ?? null} end={selectedSummary.activeStage?.plannedEnd ?? null} /><TimeGauge title="عداد المشروع" start={selectedSummary.project.plannedStart} end={selectedSummary.project.plannedEnd} /><div className="grid grid-cols-2 gap-3"><Indicator label="إنجاز المشروع" value={`${selectedSummary.progress}%`} /><Indicator label="إنجاز المرحلة" value={`${selectedSummary.activeStage?.actualProgress ?? 0}%`} /><Indicator label="الميزانية" value={`${money.format(selectedSummary.plannedBudget)} ر.س`} /><Indicator label="المنصرف" value={`${money.format(selectedSummary.actualCost)} ر.س`} /></div></section>}

          {selectedSummary && <section className="grid gap-4 md:grid-cols-2"><BudgetSummary title="مقارنة المشروع ككل — الميزانية والمنصرف" planned={selectedSummary.plannedBudget} actual={selectedSummary.actualCost} /><BudgetSummary title={`مقارنة المرحلة الحالية — ${selectedSummary.activeStage?.name ?? "لا توجد مرحلة نشطة"}`} planned={selectedSummary.activeStage?.plannedBudget ?? 0} actual={selectedSummary.activeStage?.actualCost ?? 0} /></section>}

          {selectedSummary && <LiquiditySummary cashFlow={selectedCashFlow} onOpenReport={() => setLocation("/reports")} />}

          {selectedSummary && <DashboardStageDetail rows={selectedDetailReport?.rows.filter((row) => row.rowType === "stage") ?? []} budgetParents={selectedDetailReport?.budgetParents ?? []} total={selectedDetailReport?.total ?? null} onOpenReport={() => setLocation("/projects")} />}

          <section className="rounded-3xl border border-[#b28a3b]/30 bg-white p-5 shadow-lg sm:p-7">
            <div className="flex flex-wrap items-start justify-between gap-4 border-b border-slate-100 pb-5"><div><p className="text-sm font-semibold tracking-wide text-[#b28a3b]">الملخص المالي العام</p><h2 className="mt-1 text-2xl font-bold text-[#18324b] sm:text-3xl">ملخص مالي للشركة ككل</h2><p className="mt-2 text-sm leading-6 text-slate-500">إجماليات الشركة كاملة، مع فصل تكلفة المشاريع عن المصروفات المشتركة وتوزيعها على المشاريع النشطة حسب قيمة العقد.</p></div><Badge variant="outline" className="border-[#b28a3b]/40 bg-[#fffaf0] px-3 py-1 text-[#8a6825]">أساس التوزيع: قيمة العقد</Badge></div>
            <div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-5"><CompanyMetric label="إجمالي تكاليف المشاريع" value={companySummary?.projectCosts ?? 0} tone="blue" /><CompanyMetric label="إجمالي إيراد المشاريع" value={companySummary?.projectRevenue ?? 0} tone="green" /><CompanyMetric label="المصروفات الإدارية" value={companySummary?.administrativeExpenses ?? 0} tone="amber" /><CompanyMetric label="المصروفات النثرية" value={companySummary?.pettyCashExpenses ?? 0} tone="slate" /><CompanyMetric label="الرواتب الإدارية للشركة" value={companySummary?.administrativePayroll ?? 0} tone="violet" /></div>
            <div className="mt-5 rounded-2xl bg-[#f7f8fa] p-4"><div className="flex flex-wrap items-end justify-between gap-2"><div><h3 className="font-bold text-[#18324b]">تحميل المصروفات الإدارية والرواتب على المشاريع النشطة</h3><p className="mt-1 text-xs text-slate-500">الإجمالي المشترك الموزع: <b className="text-[#18324b]">{money.format(companySummary?.sharedTotal ?? 0)} ر.س</b></p></div><span className="text-xs text-slate-500">لا تُضاف هذه القيم مرة أخرى إلى تكلفة المشروع المباشرة.</span></div><div className="mt-4 overflow-x-auto">{companySummary?.activeProjects?.length ? <table className="w-full min-w-[720px] text-right text-sm"><thead><tr className="border-b border-slate-200 bg-[#18324b] text-white"><th className="p-3">المشروع</th><th className="p-3">قيمة العقد</th><th className="p-3">نسبة التحمل</th><th className="p-3">إداري</th><th className="p-3">نثريات</th><th className="p-3">رواتب إدارية</th><th className="p-3">إجمالي التحميل</th></tr></thead><tbody>{companySummary.activeProjects.map((item) => <tr key={item.projectId} className="border-b border-slate-100 bg-white"><td className="p-3 font-semibold text-[#18324b]">{item.projectName}</td><td className="p-3">{money.format(item.contractValue)} ر.س</td><td className="p-3 font-bold text-[#b28a3b]">{(item.ratio * 100).toFixed(2)}%</td><td className="p-3">{money.format(item.administrativeExpenses ?? 0)} ر.س</td><td className="p-3">{money.format(item.pettyCashExpenses ?? 0)} ر.س</td><td className="p-3">{money.format(item.administrativePayroll ?? 0)} ر.س</td><td className="p-3 font-bold text-[#18324b]">{money.format(item.allocatedAmount)} ر.س</td></tr>)}</tbody></table> : <p className="py-8 text-center text-sm text-slate-500">لا توجد مشاريع نشطة ذات قيمة عقد حتى الآن لتوزيع المصروفات المشتركة.</p>}</div></div>
          </section>

          <section className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6">
            <MetricCard icon={HardHat} label="تكاليف مقاولي الباطن" value={`${money.format(selectedSummary ? selectedSummary.subcontractorCostsTotal : shortcutTotals.subcontractorCostsTotal)} ر.س`} hint="من إجمالي المستخلصات المعتمدة" tone="slate" onClick={() => setLocation("/operations?tab=certificates")} />
            <MetricCard icon={Landmark} label="تقرير تكلفة الخامات" value={`${money.format(selectedExpenseTotals.materials)} ر.س`} hint="تفصيل الخامات في قائمة الدخل" tone="gold" onClick={() => setLocation(`/accounting?report=materials${selectedSummary ? `&projectId=${selectedSummary.project.id}` : ""}`)} />
            <MetricCard icon={WalletCards} label="التكلفة التشغيلية" value={`${money.format(selectedExpenseTotals.operational)} ر.س`} hint="تشغيل ومعدات وخدمات" tone="blue" onClick={() => setLocation("/expenses")} />
            <MetricCard icon={Clock3} label="مصروف الرواتب" value={`${money.format(selectedExpenseTotals.payroll)} ر.س`} hint="رواتب محملة على المشروع" tone="violet" onClick={() => setLocation("/payroll")} />
            <MetricCard icon={ReceiptText} label="المصاريف الإدارية والعمومية" value={`${money.format(selectedExpenseTotals.administrative)} ر.س`} hint="مصروفات إدارية معتمدة" tone="amber" onClick={() => setLocation("/expenses")} />
            <MetricCard icon={CircleDollarSign} label="إجمالي المصروفات" value={`${money.format(selectedExpenseTotals.total)} ر.س`} hint="التصنيفات الأربعة مجمعة" tone="rose" onClick={() => setLocation("/reports")} />
          </section>

          <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
            <MetricCard icon={FolderKanban} label="المشاريع النشطة" value={String(summaries.filter((item) => isProjectActive(item.project)).length)} hint={`${summaries.length} إجمالي المشاريع`} tone="blue" onClick={() => setLocation("/projects")} />
            <MetricCard icon={Landmark} label="الميزانية المخططة" value={`${money.format(totalBudget)} ر.س`} hint="من العقد والمراحل" tone="gold" onClick={() => setLocation("/reports")} />
            <MetricCard icon={WalletCards} label="التكلفة الفعلية" value={`${money.format(totalActual)} ر.س`} hint={`${money.format(totalOutstanding)} ر.س مستحق`} tone="rose" onClick={() => setLocation("/finance")} />
            <MetricCard icon={ReceiptText} label="المصروفات المستحقة" value={`${money.format(totalOutstanding + totalPayrollOutstanding)} ر.س`} hint="تكاليف ورواتب غير مدفوعة" tone="amber" onClick={() => setLocation("/finance")} />
            <MetricCard icon={CircleDollarSign} label="الإيراد المعترف به" value={`${money.format(totalRevenue)} ر.س`} hint="من مبيعات الوحدات" tone="green" onClick={() => setLocation("/sales")} />
            <MetricCard icon={HandCoins} label="التحصيلات" value={`${money.format(totalCollections)} ر.س`} hint="الدفعات المستلمة" tone="teal" onClick={() => setLocation("/sales")} />
            <MetricCard icon={Clock3} label="رواتب مستحقة" value={`${money.format(totalPayrollOutstanding)} ر.س`} hint="غير مدفوعة حتى الآن" tone="violet" onClick={() => setLocation("/finance")} />
            <MetricCard icon={WalletCards} label="فجوة السيولة" value={`${money.format(totalCashGap)} ر.س`} hint="تمويل مطلوب" tone="rose" onClick={() => setLocation("/reports")} />
            <MetricCard icon={FileCheck2} label="موافقات معلقة" value={String(totalPendingApprovals)} hint={`${criticalCount} حالة حرجة`} tone="slate" onClick={() => setLocation("/approvals")} />
          </section>

          {user?.role === "general_manager" && <section className="space-y-5 rounded-3xl border border-[#b28a3b]/25 bg-white p-5 shadow-sm sm:p-7"><div className="flex flex-wrap items-end justify-between gap-3 border-b border-slate-100 pb-4"><div><p className="text-sm font-semibold tracking-wide text-[#b28a3b]">مركز القرار التنفيذي</p><h2 className="mt-1 text-2xl font-bold text-[#18324b]">ما يحتاج انتباهك الآن</h2><p className="mt-2 text-sm text-slate-500">ملخص للقرارات والمخاطر والسيولة من واقع المستندات والمعاملات المسجلة.</p></div><Button variant="outline" onClick={() => setLocation("/approvals")} className="gap-2">فتح كل الموافقات <ArrowLeft className="h-4 w-4" /></Button></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><ExecutiveActionCard label="موافقات معلقة" value={approvalRows.filter((row) => row.status === "pending").length} hint="قرارات تنتظر الاعتماد" tone="amber" onClick={() => setLocation("/approvals")} /><ExecutiveActionCard label="مشاريع حرجة" value={criticalCount} hint="تجاوز تكلفة أو وقت" tone="rose" onClick={() => setLocation("/reports")} /><ExecutiveActionCard label="مشاريع تحتاج متابعة" value={warningCount} hint="إشارة مبكرة للانحراف" tone="blue" onClick={() => setLocation("/reports")} /><ExecutiveActionCard label="التزامات غير مدفوعة" value={money.format(totalOutstanding + totalPayrollOutstanding)} hint="تكاليف ورواتب مستحقة · ر.س" tone="violet" onClick={() => setLocation("/finance")} /></div><div className="grid gap-4 lg:grid-cols-[1fr_1.2fr]"><div className="rounded-2xl bg-[#18324b] p-5 text-white"><div className="flex items-center justify-between"><div><p className="text-sm text-slate-300">مؤشر السيولة للشركة</p><p className="mt-2 text-3xl font-bold">{money.format(totalCollections - totalActual)} ر.س</p></div><WalletCards className="h-8 w-8 text-[#d7b76b]" /></div><p className="mt-3 text-xs leading-6 text-slate-300">صافي الحركة الحالية = التحصيلات المسجلة ناقص التكلفة الفعلية المسجلة. لا يمثل رصيد البنوك إلا بعد مراجعة حسابات النقد والبنوك.</p><div className="mt-4 flex flex-wrap gap-2 text-xs"><span className="rounded-full bg-white/10 px-3 py-1">تحصيلات {money.format(totalCollections)} ر.س</span><span className="rounded-full bg-white/10 px-3 py-1">تكلفة فعلية {money.format(totalActual)} ر.س</span><span className="rounded-full bg-white/10 px-3 py-1">فجوة مسجلة {money.format(totalCashGap)} ر.س</span></div></div><div className="rounded-2xl border border-slate-100 bg-[#f8fafc] p-5"><div className="flex items-center gap-2"><ShieldAlert className="h-5 w-5 text-rose-600" /><h3 className="font-bold text-[#18324b]">تنبيهات تستحق المراجعة</h3></div><div className="mt-4 space-y-2">{summaries.filter((item) => item.status !== "on_track" || item.delayedStages > 0 || item.cashGap > 0).slice(0, 5).map((item) => <div key={item.project.id} className="flex w-full items-center justify-between gap-3 rounded-xl bg-white p-3 text-right shadow-sm transition hover:ring-1 hover:ring-[#b28a3b]/50"><button type="button" onClick={() => setSelectedProjectId(item.project.id)} className="min-w-0 flex-1 text-right"><span><b className="block text-sm text-[#18324b]">{item.project.name}</b><span className="mt-1 block text-xs text-slate-500">{item.status === "critical" ? "حالة حرجة" : item.delayedStages > 0 ? `${item.delayedStages} مرحلة متأخرة` : "يحتاج متابعة"}</span></span></button><div className="flex items-center gap-2"><span className="text-xs font-bold text-rose-700">{money.format(item.cashGap)} ر.س</span><Button type="button" size="sm" variant="outline" disabled={sendProjectAlert.isPending} onClick={() => { const message = window.prompt(`اكتب رسالة سريعة لمدير مشروع ${item.project.name}:`, item.status === "critical" ? "يرجى مراجعة حالة المشروع واتخاذ الإجراء العاجل." : "يرجى متابعة مؤشرات المشروع وتحديثنا بالإجراء المطلوب."); if (message?.trim()) sendProjectAlert.mutate({ projectId: item.project.id, message: message.trim() }); }} className="gap-1 border-[#b28a3b]/40 text-[#8b6b2f]"><MessageSquare className="h-3.5 w-3.5" /> إرسال تنبيه</Button></div></div>)}{summaries.filter((item) => item.status !== "on_track" || item.delayedStages > 0 || item.cashGap > 0).length === 0 && <p className="py-5 text-center text-sm text-emerald-700">لا توجد تنبيهات حرجة حسب البيانات الحالية.</p>}</div></div></div></section>}

          <section className="grid gap-5 lg:grid-cols-[1.4fr_0.6fr]">
            <Card className="border-0 shadow-sm">
              <CardHeader className="flex flex-row items-center justify-between border-b border-slate-100 pb-4">
                <div>
                  <CardTitle className="text-lg text-[#18324b]">صحة المشاريع</CardTitle>
                  <p className="mt-1 text-xs text-slate-500">مقارنة مباشرة بين المخطط والفعلي لكل مشروع</p>
                </div>
                <Button variant="ghost" className="gap-1 text-[#18324b]" onClick={() => setLocation("/reports")}>كل التقارير <ArrowLeft className="h-4 w-4" /></Button>
              </CardHeader>
              <CardContent className="space-y-4 pt-5">
                {isLoading ? <div className="py-12 text-center text-sm text-slate-500">جارٍ تحميل مؤشرات المشاريع...</div> : summaries.length === 0 ? <EmptyProjects onAdd={() => setLocation("/projects")} /> : summaries.map((item) => {
                  const status = statusLabels[item.status as keyof typeof statusLabels] ?? statusLabels.warning;
                  return <div key={item.project.id} className="cursor-pointer rounded-2xl border border-slate-100 bg-white p-4 transition hover:border-[#b28a3b]/40 hover:shadow-sm" onClick={() => setLocation(`/projects/${item.project.id}`)}>
                    <div className="flex flex-wrap items-start justify-between gap-3">
                      <div>
                        <div className="flex flex-wrap items-center gap-2"><h3 className="font-bold text-[#18324b]">{item.project.name}</h3><Badge variant="outline" className={status.className}>{status.label}</Badge><Badge className={item.project.classification === "administrative" ? "bg-amber-100 text-amber-800" : "bg-blue-100 text-blue-800"}>{classificationLabels[item.project.classification] ?? item.project.classification}</Badge></div>
                        <p className="mt-1 text-xs text-slate-500">{item.project.code}{item.project.location ? ` · ${item.project.location}` : ""} · {item.stageCount} مراحل</p>
                      </div>
                      <div className="text-left"><p className="text-xs text-slate-500">استخدام الميزانية</p><p className={`text-xl font-bold ${item.budgetUsage >= 100 ? "text-rose-600" : item.budgetUsage >= 80 ? "text-amber-600" : "text-[#18324b]"}`}>{item.budgetUsage}%</p></div>
                    </div>
                    <div className="mt-4 grid gap-4 md:grid-cols-[1fr_auto] md:items-center"><div><div className="mb-2 flex justify-between text-xs text-slate-500"><span>إنجاز المراحل {item.progress}%</span><span>فعلي {money.format(item.actualCost)} / مخطط {money.format(item.plannedBudget)} ر.س</span></div><Progress value={Math.min(item.progress, 100)} className="h-2" /></div><div className="text-left text-xs text-slate-500">{item.delayedStages ? `${item.delayedStages} مرحلة متأخرة` : "لا توجد مراحل متأخرة"}</div></div><div className="mt-4 flex flex-wrap gap-2 border-t border-slate-100 pt-3">{item.reasons.map((reason) => <span key={reason} className={`rounded-full px-2.5 py-1 text-xs ${item.status === "critical" ? "bg-rose-50 text-rose-700" : item.status === "warning" ? "bg-amber-50 text-amber-700" : "bg-emerald-50 text-emerald-700"}`}>{reason}</span>)}</div>
                  </div>;
                })}
              </CardContent>
            </Card>

            <Card className="border-0 bg-[#18324b] text-white shadow-sm">
              <CardHeader><CardTitle className="text-lg">مؤشر الإدارة</CardTitle><p className="text-sm leading-6 text-slate-300">الأرقام الحمراء لا تكتفي بالتنبيه؛ النظام سيقودك إلى سبب الانحراف والإجراء المطلوب.</p></CardHeader>
              <CardContent className="space-y-4"><InsightRow icon={CheckCircle2} label="مشاريع على المسار" value={String(summaries.filter((item) => item.status === "on_track").length)} tone="text-emerald-300" /><InsightRow icon={CalendarClock} label="مراحل تحتاج متابعة" value={String(summaries.reduce((sum, item) => sum + item.delayedStages, 0))} tone="text-amber-300" /><InsightRow icon={ShieldAlert} label="قرارات حرجة" value={String(criticalCount)} tone="text-rose-300" /><div className="border-t border-white/10 pt-4 text-xs leading-6 text-slate-300">الخطوة التالية: إنشاء المشاريع والمراحل ثم تسجيل أول معاملة مالية ليبدأ المؤشر في بناء الصورة التنفيذية.</div></CardContent>
            </Card>
          </section>
        </div>
      </div>
    </DashboardLayout>
  );
}

type BudgetOverviewView = { project: { name: string }; plannedBudget: number; plannedRevenue?: number; plannedZakat?: number; plannedProfit?: number; actualCost: number; paidCost: number; outstandingCost: number };
function BudgetOverview({ summary, budgetParents }: { summary: BudgetOverviewView; budgetParents: Array<{ id: number; name: string; plannedBudget: number; allocated: number; available: number; actual: number; allocationPct: number }> }) {
  const plannedCost = Number(summary.plannedBudget || 0);
  const actual = Number(summary.actualCost || 0);
  const variance = plannedCost - actual;
  const metrics = [{ label: "الإيراد المخطط", value: Number(summary.plannedRevenue || 0), tone: "text-blue-700" }, { label: "التكلفة المخططة", value: plannedCost, tone: "text-[#18324b]" }, { label: "التكلفة الفعلية", value: actual, tone: "text-rose-700" }, { label: "المدفوع فعليًا", value: Number(summary.paidCost || 0), tone: "text-emerald-700" }, { label: "المستحق", value: Number(summary.outstandingCost || 0), tone: "text-amber-700" }, { label: "الربح المخطط", value: Number(summary.plannedProfit || 0), tone: "text-violet-700" }];
  return <Card className="border-0 bg-white shadow-sm"><CardHeader className="border-b border-slate-100"><div className="flex flex-wrap items-center justify-between gap-3"><div><CardTitle className="text-xl text-[#18324b]">الموازنة الشاملة للمشروع</CardTitle><p className="mt-1 text-xs leading-6 text-slate-500">{summary.project.name} · المخطط محفوظ مستقلًا عن الفواتير وسندات الصرف والمستخلصات. الإدخالات الفعلية التي تنشئونها لاحقًا ستظهر هنا فقط بعد ربطها بالمشروع وبند التكلفة.</p></div><Badge className="bg-[#f5f0e5] text-[#8a6825]">مخطط مقابل فعلي</Badge></div></CardHeader><CardContent className="space-y-5">{budgetParents.length > 0 && <div className="rounded-2xl border border-[#b28a3b]/30 bg-[#fffaf0] p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-xs font-semibold text-[#8a6825]">توزيع موازنة البناء</p><p className="mt-1 text-sm font-bold text-[#18324b]">الحساب الأب والفروع التابعة</p></div><span className="text-xs text-slate-500">لا يوجد احتساب مزدوج</span></div><div className="mt-3 grid gap-3 sm:grid-cols-2">{budgetParents.map((parent) => <div key={parent.id} className="rounded-xl bg-white p-3"><div className="flex items-center justify-between gap-2"><span className="font-semibold text-[#18324b]">{parent.name}</span><span className="text-[11px] text-[#8a6825]">{parent.allocationPct.toFixed(1)}% مخصص</span></div><div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-slate-600"><span>السقف: <b>{money.format(parent.plannedBudget)} ر.س</b></span><span>للمراحل: <b>{money.format(parent.allocated)} ر.س</b></span><span className={parent.available < 0 ? "text-rose-700" : "text-emerald-700"}>المتاح: <b>{money.format(parent.available)} ر.س</b></span></div></div>)}</div></div>}<div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6">{metrics.map((metric) => <div key={metric.label} className="rounded-xl border border-slate-100 bg-slate-50 p-3"><p className="text-xs text-slate-500">{metric.label}</p><p className={`mt-2 text-lg font-bold ${metric.tone}`}>{money.format(metric.value)} <span className="text-xs font-normal">ر.س</span></p></div>)}</div><div className="grid gap-4 lg:grid-cols-[1fr_280px]"><div><div className="mb-2 flex justify-between text-xs text-slate-500"><span>استهلاك التكلفة المخططة</span><span>{plannedCost ? `${((actual / plannedCost) * 100).toFixed(1)}%` : "—"}</span></div><Progress value={plannedCost ? Math.min((actual / plannedCost) * 100, 100) : 0} className="h-3" /><div className="mt-3 flex flex-wrap gap-2 text-xs"><span className="rounded-full bg-slate-100 px-3 py-1 text-slate-600">الزكاة المخططة: {money.format(Number(summary.plannedZakat || 0))} ر.س</span><span className={`rounded-full px-3 py-1 ${variance < 0 ? "bg-rose-50 text-rose-700" : "bg-emerald-50 text-emerald-700"}`}>{variance < 0 ? "تجاوز المخطط" : "الرصيد المتبقي من المخطط"}: {money.format(Math.abs(variance))} ر.س</span></div></div><div className="rounded-2xl bg-[#18324b] p-4 text-white"><p className="text-xs text-slate-300">قراءة الإدارة</p><p className="mt-2 text-sm font-semibold">{actual === 0 ? "لا توجد حركات فعلية مسجلة حتى الآن" : variance < 0 ? "التكلفة الفعلية تجاوزت المخطط" : "التكلفة الفعلية داخل حدود المخطط"}</p><p className="mt-2 text-xs leading-5 text-slate-300">يتم إدخال الحركات من صفحاتها المعتادة، ولا تُنشأ أي حركات تلقائيًا من الموازنة.</p></div></div></CardContent></Card>;
}

function DashboardStageDetail({ rows, budgetParents, total, onOpenReport }: { rows: Array<{ rowType: "stage" | "costItem"; id: number; code: string; name: string; stageName: string; plannedBudget: number; actual: number; paidAmount: number; outstanding: number; variance: number; consumptionPct: number; timeVarianceDays: number; status: string }>; budgetParents: Array<{ id: number; code: string; name: string; plannedBudget: number; allocated: number; available: number; actual: number; allocationPct: number }>; total: { plannedBudget: number; actual: number; paidAmount: number; outstanding: number; variance: number; consumptionPct: number } | null; onOpenReport: () => void }) {
  return <Card className="border-0 shadow-sm"><CardHeader className="flex flex-row items-center justify-between"><div><CardTitle className="text-lg text-[#18324b]">تفصيل أداء وتكلفة مراحل البناء</CardTitle><p className="mt-1 text-xs text-slate-500">مراحل البناء الفعلية للمشروع المختار، مع الأداء والميزانية والمنصرف والانحراف الزمني.</p></div><Button variant="outline" size="sm" onClick={onOpenReport}>فتح تفصيل المشاريع</Button></CardHeader><CardContent className="overflow-x-auto">{budgetParents.length > 0 && <div className="mb-4 grid gap-3 md:grid-cols-2">{budgetParents.map((parent) => <div key={parent.id} className="rounded-2xl border border-[#b28a3b]/30 bg-[#fffaf0] p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-semibold text-[#8a6825]">حساب أب للمراحل</p><p className="mt-1 font-bold text-[#18324b]">{parent.name}</p><p className="mt-1 text-[11px] text-slate-500">الفروع التابعة تُخصم من سقف هذا الحساب</p></div><span className="rounded-full bg-white px-2 py-1 text-[11px] font-semibold text-[#8a6825]">تخصيص {parent.allocationPct.toFixed(1)}%</span></div><div className="mt-3 grid grid-cols-3 gap-2 text-[11px]"><div className="rounded-lg bg-white p-2"><span className="text-slate-500">السقف</span><strong className="mt-1 block text-[#18324b]">{money.format(parent.plannedBudget)}</strong></div><div className="rounded-lg bg-white p-2"><span className="text-slate-500">المخصص</span><strong className="mt-1 block text-[#18324b]">{money.format(parent.allocated)}</strong></div><div className="rounded-lg bg-white p-2"><span className="text-slate-500">المتاح</span><strong className={`mt-1 block ${parent.available < 0 ? "text-rose-700" : "text-emerald-700"}`}>{money.format(parent.available)}</strong></div></div></div>)}</div>}<table className="w-full min-w-[1000px] text-right text-xs"><thead><tr className="bg-[#18324b] text-white"><th className="px-3 py-3">الكود</th><th className="px-3 py-3">مرحلة البناء</th><th className="px-3 py-3">المخطط</th><th className="px-3 py-3">الفعلي</th><th className="px-3 py-3">المدفوع</th><th className="px-3 py-3">المستحق</th><th className="px-3 py-3">الانحراف</th><th className="px-3 py-3">الاستهلاك</th><th className="px-3 py-3">انحراف الوقت</th><th className="px-3 py-3">الحالة</th></tr></thead><tbody>{rows.length ? rows.map((row) => <tr key={`${row.rowType}-${row.id}`} className="border-b border-slate-100 odd:bg-slate-50"><td className="px-3 py-3 font-semibold text-[#18324b]">{row.code}</td><td className="px-3 py-3"><b>{row.name}</b></td><td className="px-3 py-3">{money.format(row.plannedBudget)}</td><td className="px-3 py-3">{money.format(row.actual)}</td><td className="px-3 py-3 text-emerald-700">{money.format(row.paidAmount)}</td><td className="px-3 py-3 text-amber-700">{money.format(row.outstanding)}</td><td className={`px-3 py-3 ${row.variance < 0 ? "text-rose-700" : "text-emerald-700"}`}>{money.format(row.variance)}</td><td className="px-3 py-3">{row.plannedBudget ? `${row.consumptionPct.toFixed(1)}%` : "—"}</td><td className={`px-3 py-3 ${row.timeVarianceDays > 0 ? "text-rose-700" : "text-emerald-700"}`}>{row.timeVarianceDays > 0 ? `${row.timeVarianceDays} يوم` : "لا يوجد"}</td><td className="px-3 py-3">{row.status === "completed" ? "مكتملة" : row.status === "active" ? "مستمرة" : row.status === "delayed" ? "مستمرة ومتأخرة" : "مخططة"}</td></tr>) : <tr><td colSpan={10} className="py-8 text-center text-slate-500">لا توجد مراحل بناء مسجلة لهذا المشروع.</td></tr>}</tbody><tfoot><tr className="bg-[#f5f0e5] font-bold text-[#18324b]"><td className="px-3 py-3" colSpan={2}>الإجمالي</td><td className="px-3 py-3">{money.format(total?.plannedBudget ?? 0)}</td><td className="px-3 py-3">{money.format(total?.actual ?? 0)}</td><td className="px-3 py-3">{money.format(total?.paidAmount ?? 0)}</td><td className="px-3 py-3">{money.format(total?.outstanding ?? 0)}</td><td className="px-3 py-3">{money.format(total?.variance ?? 0)}</td><td className="px-3 py-3">{total?.plannedBudget ? `${total.consumptionPct.toFixed(1)}%` : "—"}</td><td className="px-3 py-3">—</td><td /></tr></tfoot></table></CardContent></Card>;
}

function ExecutionBoard({ summary, rows }: { summary: { project: { name: string }; plannedBudget: number; actualCost: number; projectExpensesPreTax?: number; projectExpensesWithTax?: number; administrativeExpensesPreTax?: number; administrativeExpensesTotal: number; totalExpenses: number; cashGap: number; status: string; budgetUsage: number; projectTimeVarianceDays?: number; projectTimeStatus?: string; stageCount?: number; activeStage?: { id: number; name: string; plannedBudget: number; actualCost: number; actualProgress: number } | null }; rows: Array<{ id: number; code: string; name: string; plannedBudget: number; actual: number; variance: number; consumptionPct: number; timeVarianceDays: number; status: string; actualProgress: number }> }) {
  const projectCostPreTax = Number(summary.projectExpensesPreTax ?? summary.actualCost);
  const adminPreTax = Number(summary.administrativeExpensesPreTax ?? summary.administrativeExpensesTotal);
  const expensesWithTax = Number(summary.totalExpenses ?? summary.projectExpensesWithTax ?? summary.actualCost);
  const costVariance = Math.max(Number(summary.actualCost) - Number(summary.plannedBudget), 0);
  const priority = (row: typeof rows[number]) => row.timeVarianceDays > 0 || row.actual > row.plannedBudget ? "عالية" : row.actualProgress < 100 && row.status !== "completed" ? "متابعة" : "عادية";
  const note = (row: typeof rows[number]) => row.timeVarianceDays > 0 ? `متأخرة ${row.timeVarianceDays} يوم` : row.actual > row.plannedBudget ? "تجاوز فعلي للميزانية" : row.status === "completed" ? "مكتملة" : "ضمن الميزانية والوقت";
  const activeStageRow = summary.activeStage ? rows.find((row) => row.id === summary.activeStage?.id) : undefined;
  const stagePlanned = activeStageRow?.plannedBudget ?? summary.activeStage?.plannedBudget ?? 0;
  const stageActual = activeStageRow?.actual ?? summary.activeStage?.actualCost ?? 0;
  const stageRemaining = Math.max(stagePlanned - stageActual, 0);
  const stageCostVariance = Math.max(stageActual - stagePlanned, 0);
  const stageContributionPct = summary.stageCount ? ((activeStageRow?.actualProgress ?? 0) / summary.stageCount) : 0;
  const stageTimeVariance = activeStageRow?.timeVarianceDays ?? 0;
  const stageImpact = stageCostVariance > 0 ? `تجاوز ${money.format(stageCostVariance)} ر.س` : stageTimeVariance > 0 ? `تأخر ${stageTimeVariance} يوم` : "لا يوجد أثر سلبي";
  return <Card className="overflow-hidden border-0 shadow-sm"><CardHeader className="bg-[#18324b] text-white"><div className="flex flex-wrap items-center justify-between gap-3"><div><CardTitle className="text-lg">لوحة المؤشرات التنفيذية</CardTitle><p className="mt-1 text-xs text-slate-300">ملخص المشروع المختار ومراقبة مراحل البناء</p></div><Badge className="bg-white/15 text-white">{summary.project.name}</Badge></div></CardHeader><CardContent className="flex flex-col gap-0 p-0"><div className="order-2 space-y-4"><div className="rounded-t-xl bg-[#f5f0e5] px-4 py-3 text-sm font-bold text-[#18324b]">مؤشرات المشروع ككل</div><div className="grid gap-px bg-slate-200 sm:grid-cols-2 lg:grid-cols-4"><ExecutionMetric label="الميزانية المخططة" value={money.format(summary.plannedBudget)} /><ExecutionMetric label="تكلفة المشروع الفعلية" value={money.format(projectCostPreTax)} /><ExecutionMetric label="المصروفات الإدارية العامة" value={money.format(adminPreTax)} /><ExecutionMetric label="انحراف التكلفة" value={costVariance > 0 ? money.format(costVariance) : "لا يوجد"} tone={costVariance > 0 ? "danger" : "good"} /></div><div className="grid gap-px bg-slate-200 sm:grid-cols-2 lg:grid-cols-4"><ExecutionMetric label="نسبة استهلاك الميزانية" value={`${summary.budgetUsage}%`} /><ExecutionMetric label="المصروفات شامل الضريبة" value={money.format(expensesWithTax)} /><ExecutionMetric label="التمويل المطلوب" value={money.format(summary.cashGap)} tone={summary.cashGap > 0 ? "warn" : "good"} /><ExecutionMetric label="صحة المشروع" value={summary.status === "on_track" ? "مستقرة" : summary.status === "critical" ? "حرجة" : "تحتاج متابعة"} tone={summary.status === "critical" ? "danger" : summary.status === "warning" ? "warn" : "good"} /></div><div className="grid gap-px bg-slate-200 sm:grid-cols-2"><ExecutionMetric label="انحراف وقت المشروع" value={summary.projectTimeVarianceDays && summary.projectTimeVarianceDays > 0 ? `${summary.projectTimeVarianceDays} يوم` : "لا يوجد"} tone={summary.projectTimeVarianceDays && summary.projectTimeVarianceDays > 0 ? "danger" : "good"} /><ExecutionMetric label="الرصيد المتبقي للمشروع" value={money.format(Math.max(Number(summary.plannedBudget) - Number(summary.actualCost), 0))} tone="good" /></div><div className="grid gap-px bg-slate-200 sm:grid-cols-2"><ExecutionMetric label="مساهمة المرحلة في إنجاز المشروع" value={`${stageContributionPct.toFixed(1)}%`} /><ExecutionMetric label="أثر انحراف المرحلة على المشروع" value={stageImpact} tone={stageImpact === "لا يوجد أثر سلبي" ? "good" : "danger"} /></div></div><div className="order-1 space-y-4"><div className="rounded-t-xl bg-[#eaf2f8] px-4 py-3 text-sm font-bold text-[#18324b]">مؤشرات المرحلة الحالية — {summary.activeStage?.name ?? "لا توجد مرحلة نشطة"}</div><div className="grid gap-px bg-slate-200 sm:grid-cols-2 lg:grid-cols-4"><ExecutionMetric label="ميزانية المرحلة الحالية" value={money.format(stagePlanned)} /><ExecutionMetric label="تكلفة المرحلة الحالية" value={money.format(stageActual)} /><ExecutionMetric label="رصيد المرحلة الحالية" value={money.format(stageRemaining)} tone="good" /><ExecutionMetric label="انحراف تكلفة المرحلة" value={stageCostVariance > 0 ? money.format(stageCostVariance) : "لا يوجد"} tone={stageCostVariance > 0 ? "danger" : "good"} /></div><div className="grid gap-px bg-slate-200 sm:grid-cols-2"><ExecutionMetric label="انحراف وقت المرحلة الحالية" value={activeStageRow?.timeVarianceDays && activeStageRow.timeVarianceDays > 0 ? `${activeStageRow.timeVarianceDays} يوم` : "لا يوجد"} tone={activeStageRow?.timeVarianceDays && activeStageRow.timeVarianceDays > 0 ? "danger" : "good"} /><ExecutionMetric label="حالة المرحلة الحالية" value={activeStageRow?.status === "completed" ? "مكتملة" : activeStageRow?.status === "delayed" ? "متأخرة" : "ضمن الخطة"} /></div><div className="overflow-x-auto"><table className="w-full min-w-[1050px] text-right text-xs"><thead><tr className="bg-[#2f78b7] text-white"><th className="px-3 py-3">المرحلة</th><th className="px-3 py-3">الميزانية</th><th className="px-3 py-3">التكلفة المنفذة</th><th className="px-3 py-3">الرصيد المتبقي</th><th className="px-3 py-3">انحراف التكلفة</th><th className="px-3 py-3">انحراف الوقت</th><th className="px-3 py-3">الحالة</th><th className="px-3 py-3">أولوية المتابعة</th><th className="px-3 py-3">ملاحظة</th></tr></thead><tbody>{rows.length ? rows.map((row) => { const costVariance = Math.max(row.actual - row.plannedBudget, 0); const remaining = Math.max(row.plannedBudget - row.actual, 0); return <tr key={row.id} className="border-b border-slate-100 odd:bg-slate-50"><td className="px-3 py-3 font-semibold text-[#18324b]">{row.name}</td><td className="px-3 py-3">{money.format(row.plannedBudget)}</td><td className="px-3 py-3">{money.format(row.actual)}</td><td className="px-3 py-3 text-emerald-700">{money.format(remaining)}</td><td className={`px-3 py-3 font-semibold ${costVariance > 0 ? "text-rose-700" : "text-emerald-700"}`}>{costVariance > 0 ? money.format(costVariance) : "لا يوجد"}</td><td className={`px-3 py-3 ${row.timeVarianceDays > 0 ? "text-rose-700" : "text-emerald-700"}`}>{row.timeVarianceDays > 0 ? `${row.timeVarianceDays} يوم` : "لا يوجد"}</td><td className="px-3 py-3">{row.status === "completed" ? "مكتملة" : row.status === "delayed" ? "متأخرة" : row.status === "active" ? "مستمرة" : "مخططة"}</td><td className="px-3 py-3">{priority(row)}</td><td className="px-3 py-3 text-slate-500">{note(row)}</td></tr>; }) : <tr><td colSpan={9} className="px-3 py-8 text-center text-slate-500">لا توجد مراحل بناء لهذا المشروع بعد.</td></tr>}</tbody></table></div></div></CardContent></Card>;
  }
function ExecutionMetric({ label, value, tone = "neutral" }: { label: string; value: string; tone?: "neutral" | "good" | "warn" | "danger" }) { const colors = { neutral: "bg-white text-[#18324b]", good: "bg-emerald-50 text-emerald-800", warn: "bg-amber-50 text-amber-800", danger: "bg-rose-50 text-rose-800" }; return <div className={`p-4 ${colors[tone]}`}><p className="text-xs opacity-70">{label}</p><p className="mt-2 text-lg font-bold">{value}</p></div>; }

function TimeGauge({ title, subtitle, start, end }: { title: string; subtitle?: string; start?: string | Date | null; end?: string | Date | null }) {
  const startDate = start ? new Date(start) : null;
  const endDate = end ? new Date(end) : null;
  const now = Date.now();
  const totalDays = startDate && endDate ? Math.max(1, Math.ceil((endDate.getTime() - startDate.getTime()) / 86400000)) : 0;
  const remainingDays = endDate ? Math.max(0, Math.ceil((endDate.getTime() - now) / 86400000)) : null;
  const elapsed = startDate && endDate ? Math.min(100, Math.max(0, ((now - startDate.getTime()) / Math.max(1, endDate.getTime() - startDate.getTime())) * 100)) : 0;
  const status = !startDate || !endDate ? "بدون تواريخ" : now < startDate.getTime() ? "لم تبدأ" : now > endDate.getTime() ? "متأخرة" : "جارية";
  const statusTone = status === "جارية" ? "text-emerald-300" : status === "متأخرة" ? "text-rose-300" : "text-amber-300";
  return <div className="rounded-2xl bg-white/10 p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-semibold text-slate-200">{title}</p>{subtitle && <p className="mt-1 text-xs text-slate-300">{subtitle}</p>}</div><Clock3 className="h-5 w-5 text-[#e0b95c]" /></div><div className="mt-3 flex items-end justify-between gap-2"><p className="text-3xl font-bold">{remainingDays === null ? "—" : `${remainingDays} يوم`}</p><span className={`text-xs font-semibold ${statusTone}`}>{status}</span></div><p className="mt-1 text-xs text-slate-300">{startDate && endDate ? `${startDate.toLocaleDateString("en-US")} → ${endDate.toLocaleDateString("en-US")} · ${totalDays} يوم` : "أدخل تاريخي البداية والنهاية"}</p><div className="mt-3 h-2 overflow-hidden rounded-full bg-white/15"><div className="h-full rounded-md bg-[#e0b95c]" style={{ width: `${elapsed}%` }} /></div></div>;
}

function Indicator({ label, value }: { label: string; value: string }) { return <div className="rounded-xl bg-white/10 p-3"><p className="text-[11px] text-slate-300">{label}</p><p className="mt-1 text-sm font-bold text-white">{value}</p></div>; }

function LiquiditySummary({ cashFlow, onOpenReport }: { cashFlow?: { cashIn: number; cashOut: number; net: number; fundingRequired: number; collections: unknown[]; stages: Array<{ stageName: string; cashIn: number; cashOut: number; net: number; fundingRequired: number }> } | null; onOpenReport: () => void }) {
  const metrics = [
    { label: "نقد داخل", value: cashFlow?.cashIn ?? 0, tone: "text-emerald-700" },
    { label: "نقد خارج", value: cashFlow?.cashOut ?? 0, tone: "text-rose-700" },
    { label: "صافي السيولة", value: cashFlow?.net ?? 0, tone: (cashFlow?.net ?? 0) >= 0 ? "text-emerald-700" : "text-rose-700" },
    { label: "تمويل مطلوب", value: cashFlow?.fundingRequired ?? 0, tone: (cashFlow?.fundingRequired ?? 0) > 0 ? "text-amber-700" : "text-emerald-700" },
  ];
  return <Card className="overflow-hidden border-0 shadow-sm"><CardHeader className="flex flex-row items-center justify-between bg-[#18324b] text-white"><div><CardTitle className="text-lg">ملخص السيولة</CardTitle><p className="mt-1 text-xs text-slate-300">حركة النقد للمشروع المختار، أسفل مقارنة الميزانية والمنصرف مباشرة.</p></div><Button variant="outline" size="sm" className="border-white/30 bg-white/10 text-white hover:bg-white/20" onClick={onOpenReport}>فتح التقرير التفصيلي</Button></CardHeader><CardContent className="p-0"><div className="grid gap-px bg-slate-200 sm:grid-cols-2 lg:grid-cols-4">{metrics.map((metric) => <div key={metric.label} className="bg-white p-4"><p className="text-xs text-slate-500">{metric.label}</p><p className={`mt-2 text-xl font-bold ${metric.tone}`}>{money.format(metric.value)} ر.س</p></div>)}<div className="bg-white p-4"><p className="text-xs text-slate-500">عدد دفعات التحصيل</p><p className="mt-2 text-xl font-bold text-[#18324b]">{cashFlow ? cashFlow.collections.length : 0}</p></div></div><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-right text-xs"><thead><tr className="bg-[#f5f0e5] text-[#18324b]"><th className="px-4 py-3">المرحلة</th><th className="px-4 py-3">نقد داخل</th><th className="px-4 py-3">نقد خارج</th><th className="px-4 py-3">صافي السيولة</th><th className="px-4 py-3">تمويل مطلوب</th></tr></thead><tbody>{cashFlow?.stages?.length ? cashFlow.stages.map((row) => <tr key={row.stageName} className="border-b border-slate-100"><td className="px-4 py-3 font-semibold text-[#18324b]">{row.stageName}</td><td className="px-4 py-3">{money.format(row.cashIn)} ر.س</td><td className="px-4 py-3">{money.format(row.cashOut)} ر.س</td><td className={`px-4 py-3 font-semibold ${row.net >= 0 ? "text-emerald-700" : "text-rose-700"}`}>{money.format(row.net)} ر.س</td><td className="px-4 py-3">{money.format(row.fundingRequired)} ر.س</td></tr>) : <tr><td colSpan={5} className="px-4 py-6 text-center text-slate-500">لا توجد حركات سيولة مرتبطة بمراحل هذا المشروع حتى الآن.</td></tr>}</tbody></table></div></CardContent></Card>;
}

function BudgetSummary({ title, planned, actual }: { title: string; planned: number; actual: number }) {
  const difference = Number(planned) - Number(actual);
  const costVariance = Math.max(Number(actual) - Number(planned), 0);
  const costVariancePct = planned ? (costVariance / Number(planned)) * 100 : 0;
  const favorable = costVariance === 0;
  const scopeLabel = title.includes("المرحلة") ? "المرحلة الحالية" : "المشروع ككل";
  return <Card className="overflow-hidden border-0 shadow-sm"><CardHeader className="bg-[#18324b] py-3 text-white"><CardTitle className="text-base">{title}</CardTitle></CardHeader><CardContent className="p-0"><div className="grid grid-cols-3 divide-x divide-x-reverse divide-slate-200 bg-[#f5f0e5] text-center text-sm font-bold text-[#18324b]"><div className="p-3"><p className="text-xs font-normal text-slate-500">ميزانية {scopeLabel}</p><p className="mt-1">{money.format(Number(planned))}</p></div><div className="p-3"><p className="text-xs font-normal text-slate-500">تكلفة {scopeLabel} فعليًا</p><p className="mt-1">{money.format(Number(actual))}</p></div><div className={`p-3 ${favorable ? "text-emerald-700" : "text-rose-700"}`}><p className="text-xs font-normal text-slate-500">رصيد {scopeLabel}</p><p className="mt-1">{money.format(Math.max(difference, 0))}</p></div></div><div className="grid grid-cols-3 divide-x divide-x-reverse divide-slate-200 text-center text-sm"><div className="p-3"><p className="text-xs text-slate-500">معدل انحراف تكلفة {scopeLabel}</p><p className={`mt-1 font-bold ${costVariancePct > 0 ? "text-rose-700" : "text-emerald-700"}`}>{costVariancePct.toFixed(1)}%</p></div><div className="p-3"><p className="text-xs text-slate-500">الحالة</p><p className={`mt-1 font-bold ${favorable ? "text-emerald-700" : "text-rose-700"}`}>{favorable ? "ضمن الميزانية" : "تجاوز الميزانية"}</p></div><div className="p-3"><p className="text-xs text-slate-500">القراءة التنفيذية</p><p className="mt-1 font-bold text-[#18324b]">{favorable ? "لا يوجد انحراف تكلفة" : "تحتاج إجراء"}</p></div></div><div className="border-t border-slate-200 bg-white p-3 text-center text-xs text-slate-500">{planned ? "المقارنة مبنية على مركز التكلفة والقيود المسجلة" : "أدخل ميزانية مركز التكلفة لعرض المقارنة"}</div></CardContent></Card>;
}

function CompanyMetric({ label, value, tone }: { label: string; value: number; tone: "blue" | "green" | "amber" | "violet" | "slate" }) { const styles = { blue: "bg-blue-50 text-blue-800", green: "bg-emerald-50 text-emerald-800", amber: "bg-amber-50 text-amber-800", violet: "bg-violet-50 text-violet-800", slate: "bg-slate-100 text-slate-800" } as const; return <div className={`rounded-2xl p-4 ${styles[tone]}`}><p className="text-xs opacity-75">{label}</p><p className="mt-2 text-xl font-bold">{money.format(value)} ر.س</p></div>; }

function MetricCard({ icon: Icon, label, value, hint, tone, onClick }: { icon: typeof FolderKanban; label: string; value: string; hint: string; tone: "blue" | "gold" | "rose" | "amber" | "green" | "teal" | "violet" | "slate"; onClick?: () => void }) {
  const colors = { blue: "bg-blue-50 text-blue-700", gold: "bg-amber-50 text-amber-700", rose: "bg-rose-50 text-rose-700", amber: "bg-orange-50 text-orange-700", green: "bg-emerald-50 text-emerald-700", teal: "bg-cyan-50 text-cyan-700", violet: "bg-violet-50 text-violet-700", slate: "bg-slate-100 text-slate-700" };
  return <Card onClick={onClick} className={`group border-0 shadow-sm transition duration-200 ${onClick ? "cursor-pointer hover:-translate-y-0.5 hover:shadow-md" : ""}`}><CardContent className="flex min-h-[132px] items-start justify-between p-5"><div><p className="text-sm text-slate-500">{label}</p><p className="mt-2 text-2xl font-bold tracking-tight text-[#18324b]">{value}</p><p className="mt-1 text-xs text-slate-400">{hint}</p></div><div className={`rounded-2xl p-3 transition group-hover:scale-105 ${colors[tone]}`}><Icon className="h-5 w-5" /></div></CardContent></Card>;
}

function ExecutiveActionCard({ label, value, hint, tone, onClick }: { label: string; value: number | string; hint: string; tone: "amber" | "rose" | "blue" | "violet"; onClick: () => void }) { const tones = { amber: "border-amber-100 bg-amber-50 text-amber-800", rose: "border-rose-100 bg-rose-50 text-rose-800", blue: "border-blue-100 bg-blue-50 text-blue-800", violet: "border-violet-100 bg-violet-50 text-violet-800" }; return <button type="button" onClick={onClick} className={`rounded-2xl border p-4 text-right transition hover:-translate-y-0.5 hover:shadow-sm ${tones[tone]}`}><p className="text-xs font-semibold">{label}</p><p className="mt-2 text-2xl font-bold">{value}</p><p className="mt-1 text-[11px] opacity-75">{hint}</p></button>; }

function InsightRow({ icon: Icon, label, value, tone }: { icon: typeof CheckCircle2; label: string; value: string; tone: string }) {
  return <div className="flex items-center justify-between rounded-xl bg-white/5 p-3"><div className="flex items-center gap-3"><Icon className={`h-5 w-5 ${tone}`} /><span className="text-sm text-slate-200">{label}</span></div><span className="text-xl font-bold">{value}</span></div>;
}

function EmptyProjects({ onAdd }: { onAdd: () => void }) {
  return <div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50 py-12 text-center"><FolderKanban className="mx-auto h-10 w-10 text-[#b28a3b]" /><h3 className="mt-3 font-bold text-[#18324b]">لا توجد مشاريع بعد</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-slate-500">ابدأ بإنشاء المشروع الأول، ثم أضف مراحله وميزانياته ليظهر لك الأداء المخطط مقابل الفعلي.</p><Button onClick={onAdd} className="mt-5 bg-[#18324b] hover:bg-[#244767]">إنشاء أول مشروع</Button></div>;
}
